#!/usr/bin/env python3
"""install_cite.py - run from the project folder (~/W):  python3 install_cite.py
Adds an "Authors" option to citations: Automatic (each style's own rule, the default) / Show all authors /
Shorten with et al. (3 or more authors). The choice is remembered in the browser and used by
  * the Cite window on the search page (APA, MLA, Chicago, Harvard)
  * "Copy All APA" on the search page
  * the Citations page (bibliography), which reloads when you change it
It swaps only the author part of the finished citation; if a citation does not look as expected it is left
untouched. Rule-based, no AI. Safe to run twice. Your own edits are kept."""
import json, os, sys

MOD = '"""citeauthors.py - the "Authors" option for citations: Automatic / Show all authors / Shorten with et al.\n\n  auto  - exactly what each style\'s own rules do (nothing changes; this is the default)\n  all   - every author is listed, in every style\n  etal  - first author + "et al." when the paper has 3 or more authors (2 authors are still both shown)\n\nIt works on the finished citation text: it finds the author part at the start of what the normal builder\nproduced and swaps only that part. If the start of a citation does not look as expected, the citation is\nreturned untouched, so a citation can never come out broken. Rule-based, no AI."""\n\nSTYLES = ("apa", "mla", "chicago", "harvard")\nMODES = ("auto", "all", "etal")\n\ndef _c():\n    import core\n    return core\n\ndef _list(style, ppl, mode):\n    """The author text a style prints for these people, for \'all\' or \'etal\'. None = nothing to change."""\n    c = _c()\n    n = len(ppl)\n    if n == 0:\n        return None\n    if style in ("apa", "harvard"):\n        names = [c._inverted(p) for p in ppl]\n        if n == 1:\n            return names[0]\n        if mode == "etal":\n            return None if n == 2 else names[0] + (", et al." if style == "apa" else " et al.")\n        if style == "apa":\n            return ", ".join(names[:-1]) + ", & " + names[-1]\n        return ", ".join(names[:-1]) + " and " + names[-1]\n    first = c._inverted(ppl[0], full=True)\n    if n == 1:\n        return first\n    if mode == "etal":\n        return None if n == 2 else first + ", et al."\n    names = [first] + [c._natural(p) for p in ppl[1:]]\n    return f"{names[0]}, and {names[1]}" if n == 2 else ", ".join(names[:-1]) + ", and " + names[-1]\n\ndef _auto(style, ppl):\n    """The author text the normal builders print (same rules as core.py)."""\n    c = _c()\n    n = len(ppl)\n    if n == 0:\n        return None\n    if style == "apa":\n        names = [c._inverted(p) for p in ppl]\n        if n == 1: return names[0]\n        if n <= 20: return ", ".join(names[:-1]) + ", & " + names[-1]\n        return ", ".join(names[:19]) + ", … " + names[-1]\n    if style == "harvard":\n        names = [c._inverted(p) for p in ppl]\n        if n == 1: return names[0]\n        if n <= 3: return ", ".join(names[:-1]) + " and " + names[-1]\n        return names[0] + " et al."\n    if style == "mla":\n        if n == 1: return c._inverted(ppl[0], full=True)\n        if n == 2: return f"{c._inverted(ppl[0], full=True)}, and {c._natural(ppl[1])}"\n        return f"{c._inverted(ppl[0], full=True)}, et al"\n    shown = ppl if n <= 10 else ppl[:7]\n    names = [c._inverted(shown[0], full=True)] + [c._natural(p) for p in shown[1:]]\n    if n > 10: return ", ".join(names) + ", et al."\n    if len(names) == 1: return names[0]\n    if len(names) == 2: return f"{names[0]}, and {names[1]}"\n    return ", ".join(names[:-1]) + ", and " + names[-1]\n\ndef apply(cites, authors, mode):\n    """cites = {\'apa\':..., \'mla\':..., \'chicago\':..., \'harvard\':...}. Returns a (possibly) changed copy."""\n    if mode not in ("all", "etal") or not isinstance(cites, dict):\n        return cites\n    try:\n        c = _c()\n        ppl = c._people(authors if isinstance(authors, list) else [])\n        out = dict(cites)\n        for style in STYLES:\n            base = cites.get(style)\n            old, new = _auto(style, ppl), _list(style, ppl, mode)\n            if not base or old is None or new is None:\n                continue\n            if style == "harvard":\n                a, b = old, new\n            else:\n                a, b = c._dot(old), c._dot(new)\n            if a != b and base.startswith(a):\n                out[style] = b + base[len(a):]\n        return out\n    except Exception:\n        return cites\n'
SPEC = json.loads('{"search.py": [["from bs4 import BeautifulSoup as BS\\n", "from bs4 import BeautifulSoup as BS\\nimport citeauthors\\n"], ["    return jsonify(_all_citations(\\n        data.get(\\"authors\\"), data.get(\\"year\\"), str(data.get(\\"title\\"))[:600],", "    return jsonify(citeauthors.apply(_all_citations(\\n        data.get(\\"authors\\"), data.get(\\"year\\"), str(data.get(\\"title\\"))[:600],"], ["        data.get(\\"pages\\"), data.get(\\"doi\\"), str(data.get(\\"oa_url\\") or \\"\\")[:500]))\\n", "        data.get(\\"pages\\"), data.get(\\"doi\\"), str(data.get(\\"oa_url\\") or \\"\\")[:500]),\\n        data.get(\\"authors\\"), data.get(\\"authors_mode\\")))\\n"], ["    papers = data.get(\\"papers\\")\\n", "    papers = data.get(\\"papers\\")\\n    mode   = data.get(\\"authors_mode\\")\\n"], ["            out.append(_all_citations(authors, str(p.get(\\"year\\") or \\"n.d.\\"), str(p.get(\\"title\\") or \\"\\"),\\n", "            out.append(citeauthors.apply(_all_citations(authors, str(p.get(\\"year\\") or \\"n.d.\\"), str(p.get(\\"title\\") or \\"\\"),\\n"], ["                                      str(p.get(\\"doi\\") or \\"\\"), str(p.get(\\"oa_url\\") or \\"\\")[:500]))\\n", "                                      str(p.get(\\"doi\\") or \\"\\"), str(p.get(\\"oa_url\\") or \\"\\")[:500]), authors, mode))\\n"]], "index.html": [["  <button class=\\"btn sm\\" onclick=\\"copyAllAPA()\\">📋 Copy All APA</button>\\n", "  <button class=\\"btn sm\\" onclick=\\"copyAllAPA()\\">📋 Copy All APA</button>\\n  <select id=\\"toolAuthors\\" class=\\"btn sm\\" onchange=\\"setCiteMode(this.value)\\" title=\\"How authors appear in copied and generated citations\\"><option value=\\"auto\\">Automatic (follows the style)</option><option value=\\"all\\">Show all authors</option><option value=\\"etal\\">Shorten with et al.</option></select>\\n"], ["function copyAllAPA() {\\n  const refs = [...new Set(currentResults.map(i=>i.apa_reference||\'\').filter(Boolean))];\\n", "// ── Citation authors option (Automatic / Show all / Shorten with et al.) ──\\nconst CITE_MODE_KEY = \'sturch_cite_authors\';\\nfunction citeMode() { try { const v = localStorage.getItem(CITE_MODE_KEY); return (v === \'all\' || v === \'etal\') ? v : \'auto\'; } catch(e) { return \'auto\'; } }\\nfunction setCiteMode(v) { try { localStorage.setItem(CITE_MODE_KEY, v); } catch(e) {} }\\nfunction citeModeOptions() {\\n  const m = citeMode();\\n  return [[\'auto\', \'Automatic (follows the style)\'], [\'all\', \'Show all authors\'], [\'etal\', \'Shorten with et al.\']]\\n    .map(o => \'<option value=\\"\' + o[0] + \'\\"\' + (o[0] === m ? \' selected\' : \'\') + \'>\' + o[1] + \'</option>\').join(\'\');\\n}\\nlet _curCiteStyle = \'apa\';\\nfunction citeModeChanged(idx) {\\n  const v = document.getElementById(\'citeAuthors\').value;\\n  setCiteMode(v);\\n  const t = document.getElementById(\'toolAuthors\'); if (t) t.value = v;\\n  _modalCiteCache = {};\\n  loadCiteStyle(_curCiteStyle, idx, document.getElementById(\'cb-\' + _curCiteStyle));\\n}\\ndocument.addEventListener(\'DOMContentLoaded\', () => { const s = document.getElementById(\'toolAuthors\'); if (s) s.value = citeMode(); });\\nasync function copyAllAPA() {\\n  let refs = null;\\n  if (citeMode() !== \'auto\') {\\n    try {\\n      const r = await fetch(\'/api/citations/bulk\', {method:\'POST\', headers:{\'Content-Type\':\'application/json\'}, body: JSON.stringify({authors_mode: citeMode(),\\n        papers: currentResults.map(i => ({authors:i.authors, year:i.year, title:i.title, journal:i.journal, volume:i.volume, issue:i.issue, pages:i.pages, doi:i.doi, oa_url:i.oa_url}))})});\\n      const d = await r.json();\\n      const l = (d.citations || []).map(c => (c && c.apa) || \'\').filter(Boolean);\\n      if (l.length) refs = [...new Set(l)];\\n    } catch(e) {}\\n  }\\n  if (!refs) refs = [...new Set(currentResults.map(i=>i.apa_reference||\'\').filter(Boolean))];\\n"], ["    <div id=\\"citeResult\\" style=\\"background:var(--surf2);", "    <div style=\\"margin:0 0 10px;display:flex;gap:8px;align-items:center\\"><label for=\\"citeAuthors\\" style=\\"font-size:.78rem;color:var(--muted)\\">Authors</label><select id=\\"citeAuthors\\" class=\\"btn sm\\" onchange=\\"citeModeChanged(${idx})\\">${citeModeOptions()}</select></div>\\n    <div id=\\"citeResult\\" style=\\"background:var(--surf2);"], ["  document.getElementById(\'modalOverlay\').classList.remove(\'hidden\');\\n}\\n\\nasync function loadCiteStyle(style, idx, btn) {\\n  const item = currentResults[idx];\\n  if (!item) return;\\n", "  document.getElementById(\'modalOverlay\').classList.remove(\'hidden\');\\n  _curCiteStyle = \'apa\';\\n  if (citeMode() !== \'auto\') loadCiteStyle(\'apa\', idx, document.getElementById(\'cb-apa\'));\\n}\\n\\nasync function loadCiteStyle(style, idx, btn) {\\n  const item = currentResults[idx];\\n  if (!item) return;\\n  _curCiteStyle = style;\\n"], ["body:JSON.stringify(item)});\\n    const data = await resp.json();\\n    _modalCiteCache = data;", "body:JSON.stringify(Object.assign({}, item, {authors_mode: citeMode()}))});\\n    const data = await resp.json();\\n    _modalCiteCache = data;"]], "citations.html": [["          <option value=\\"given\\">As saved</option>\\n        </select></div>\\n", "          <option value=\\"given\\">As saved</option>\\n        </select></div>\\n      <div class=\\"fg\\"><label>Authors</label><select id=\\"authorsMode\\"><option value=\\"auto\\">Automatic (follows the style)</option><option value=\\"all\\">Show all authors</option><option value=\\"etal\\">Shorten with et al.</option></select></div>\\n"], ["body: JSON.stringify({papers: papers.map(", "body: JSON.stringify({authors_mode: citeMode(), papers: papers.map("], ["$(\'source\').addEventListener(\'change\', () => chooseSource($(\'source\').value));\\n", "$(\'source\').addEventListener(\'change\', () => chooseSource($(\'source\').value));\\nconst CITE_MODE_KEY = \'sturch_cite_authors\';\\nfunction citeMode(){ try { const v = localStorage.getItem(CITE_MODE_KEY); return (v === \'all\' || v === \'etal\') ? v : \'auto\'; } catch(e) { return \'auto\'; } }\\n$(\'authorsMode\').value = citeMode();\\n$(\'authorsMode\').addEventListener(\'change\', () => { try { localStorage.setItem(CITE_MODE_KEY, $(\'authorsMode\').value); } catch(e) {} chooseSource($(\'source\').value); });\\n"]]}')

def find(name):
    for c in (name, os.path.join("routes", name), os.path.join("templates", name)):
        if os.path.isfile(c):
            return c
def read(p): return open(p, encoding="utf-8").read()
def write(p, t): open(p, "w", encoding="utf-8", newline="").write(t)

core = find("core.py")
if not core or not find("search.py"):
    print("core.py / search.py not found. Run this from the project folder (~/W)."); sys.exit(1)
ok, warn, plan = [], [], {}
for name, pairs in SPEC.items():
    p = find(name)
    if not p:
        warn.append(name + ": not found, skipped"); continue
    t = read(p); bad = []
    for old, new in pairs:
        if new in t or (new.endswith(old) and new[:-len(old)] in t):
            continue
        if t.count(old) == 1:
            t = t.replace(old, new)
        else:
            bad.append(old[:60].replace("\n", " "))
    if bad:
        warn.append(name + ": left alone, did not match: " + " | ".join(bad))
    elif t != read(p):
        plan[p] = t
if "search.py" in " ".join(warn):
    plan = {}                                       # the server part and the pages go together
for p, t in plan.items():
    write(p + ".new", t); os.replace(p + ".new", p); ok.append(p)
if not any(w.startswith("search.py") for w in warn):
    target = os.path.join(os.path.dirname(core) or ".", "citeauthors.py")
    if not os.path.isfile(target) or read(target) != MOD:
        write(target, MOD); ok.append(target)
print("Updated:", ", ".join(ok) or "nothing (already done?)")
for w in warn: print("  warning:", w)
